 function handleVoiceTool(name:string,raw:Record<string,any>):unknown{
  const args=validateToolCall(name,raw);
  if(name==='inspect_workspace')return voiceContext;
  if(name==='update_design'){const next={...params,...args.changes};setParams(next);setArea('workspace');setStep('design');setMode('material');return {applied:true,params:next,source:'illustrative-demo'};}
  if(name==='control_camera'){setArea('workspace');requestAnimationFrame(()=>viewer.current?.view(args.view));return {status:'requested',view:args.view};}
  if(name==='show_field'){
   if(args.field==='sdf'){setArea('lab');setLabMode('sdf');return {displayed:'sdf',scope:'Analytical CSG specimen, not anatomical FEM.'};}
   setArea('workspace');setMode(args.field);if(args.field!=='material')setResult(evaluate(params,caseId,'Voice field preview'));return {displayed:args.field,source:args.field==='material'?'reference geometry':'illustrative-demo'};
  }
  if(name==='run_workflow'){
   if(['analysis','search','study'].includes(args.action)){
    if(busy)throw new Error('Another preview is active. Cancel it before starting another.');
    setArea(args.action==='analysis'?'workspace':args.action==='study'?'studies':'search');return completeWorkflow(args.action);
   }
   if(args.action==='compare'){setArea('workspace');setStep('compare');setOverlay(true);return {current:voiceContext.response,baseline:voiceContext.baseline,source:'illustrative-demo'};}
   if(args.action==='save'){save();return {saved:true,storage:'this browser',source:'illustrative-demo'};}
   if(args.action==='report'){report(display,revisions);return {download_requested:true,format:'printable HTML',source:'illustrative-demo'};}
   if(args.action==='cancel'){cancel();return {cancelled:true};}
   if(args.action==='remediate'){
    if(busy)throw new Error('Cancel the active preview first.');
    const rows=search(params,caseId),winner=rows.find(r=>r.margin>=2&&r.clearance>=params.clearance);setCandidates(rows);
    if(!winner){setArea('search');return {applied:false,reason:'No candidate meets the illustrative margin and clearance targets.',source:'illustrative-demo',qualified:false};}
    setBaseline(evaluate(params,caseId,'Before remediation'));apply(winner);setOverlay(true);setStep('compare');return {applied:true,params:winner.params,stress_mpa:winner.stress,mass_g:winner.mass,source:'illustrative-demo',qualified:false};
   }
  }
  throw new Error('Unknown workspace action.');
 }
 function ask(text:string):string {
  setCommand('');
  const words:Record<string,string>={one:'1',two:'2',three:'3',four:'4',five:'5',six:'6',seven:'7',eight:'8',nine:'9',ten:'10',half:'0.5'};
  const lower=text.toLowerCase().replace(/\b(one|two|three|four|five|six|seven|eight|nine|ten|half)\b/g,w=>words[w]).replace(/(\d) point (\d)/g,'$1.$2');
  const num=lower.match(/(?:\d*\.)?\d+/),value=num?Number(num[0]):null;
  let response='I can change thickness, width, advancement or loading; inspect the response; move the camera; explore alternatives; or run a cohort study. What would you like to do?';
  const field=lower.includes('thick')?'thickness':lower.includes('width')||lower.includes('wider')?'width':lower.includes('advanc')?'advancement':lower.includes('screw')&&lower.includes('length')?'screwLength':lower.includes('trajectory')||lower.includes('angle')?'angle':lower.includes('load')&&value!==null?'load':lower.includes('modulus')?'modulus':lower.includes('buffer')?'clearance':null;
  if(field){
   const bounds:Record<string,[number,number,number,string]>={thickness:[1,3.5,.3,'millimeters'],width:[2,6,.5,'millimeters'],advancement:[2,8,.5,'millimeters'],screwLength:[4,16,1,'millimeters'],angle:[-20,20,5,'degrees'],load:[100,1000,100,'newtons'],modulus:[450,1900,100,'megapascals'],clearance:[2,8,.5,'millimeters']};
   const [min,max,increment,unit]=bounds[field];const down=/decreas|reduc|thinner|narrower|less|shorter/.test(lower),relative=/by |increas|decreas/.test(lower);
   const requested=value===null?params[field]+(down?-increment:increment):relative?params[field]+(down?-value:value):value;
   const next=Math.max(min,Math.min(max,Math.round(requested*100)/100));update(field,next);setArea('workspace');setStep(field==='load'||field==='modulus'?'analyze':'design');setMode('material');
   response=`${field==='screwLength'?'Screw length':field[0].toUpperCase()+field.slice(1)} is now ${next} ${unit}. The design has updated.`;
  }else if(/brief|what am i|explain the design|what is this/.test(lower)){
   setArea('workspace');setStep('design');setMode('material');response=`You are looking at ${caseNames[caseId]}, a CT-derived mandible with bilateral fixation. The plate is ${params.thickness} millimeters thick and ${params.width} millimeters wide, with ${params.advancement} millimeters of advancement. You can ask me to change the design, inspect the response, compare alternatives, or run a cohort study.`;
  }else if(/inspect|tell me.*stress|how.*stress|response|results/.test(lower)){
   setArea('workspace');setStep('analyze');setResult(evaluate(params,caseId,'Response inspection'));setMode('stress');response=`The illustrative response is ${current.stress.toFixed(1)} megapascals peak stress and ${current.displacement.toFixed(3)} millimeters displacement under ${params.load} newtons. These are presentation estimates, not validated predictions. I have opened the stress view.`;
  }else if(/remediat|fix the|reduce stress|apply.*best/.test(lower)){
   const options=search(params,caseId),winner=options.find(r=>r.margin>=2&&r.clearance>=params.clearance);setCandidates(options);
   if(winner){apply(winner);setBaseline(evaluate(params,caseId,'Before remediation'));setOverlay(true);setStep('compare');response=`I explored 16 configurations and applied a ${winner.params.thickness} by ${winner.params.width} millimeter candidate meeting the illustrative margin and clearance targets. Compare it with the previous design. This is proxy-based exploration, not a qualified recommendation.`;}else{setArea('search');response='No candidate met both illustrative targets. I have opened the candidates so you can review the trade-offs.';}
  }else if(/study|cohort/.test(lower)){setArea('studies');play('study');response='Opening the cohort study: 2 reference anatomies, 3 loading directions and 3 material assumptions. Eighteen illustrative scenarios, with an exportable comparison.';
  }else if(/best|optimi|search|alternative/.test(lower)){setArea('search');play('search');response='Exploring 16 combinations of plate thickness and width. Select a candidate to inspect its geometry and compare the trade-offs.';
  }else if(/distance|sdf|implicit/.test(lower)){setArea('lab');setLabMode('sdf');response='This is the analytical signed-distance field. The zero contour marks the boundary, negative values are inside, and positive values are outside. The field changes with the geometry while the background grid stays independent.';
  }else if(/report|export/.test(lower)){report(display,revisions);response='Your report has been downloaded. Open it and choose Print to save a PDF.';
  }else if(/compar|baseline/.test(lower)){setArea('workspace');setStep('compare');setOverlay(true);response=`Baseline comparison is open. The current illustrative stress is ${Math.abs(changed).toFixed(1)} percent ${changed<=0?'lower':'higher'} than the starting design.`;
  }else if(/cancel|stop the/.test(lower)){cancel();response='The current preview is stopped. Your design is retained.';
  }else if(/left.*(view|camera)|rotate.*left|look.*left/.test(lower)){setArea('workspace');requestAnimationFrame(()=>viewer.current?.view('left'));response='Moving to the left view.';
  }else if(/right.*(view|camera)|rotate.*right/.test(lower)){setArea('workspace');requestAnimationFrame(()=>viewer.current?.view('right'));response='Moving to the right view.';
  }else if(/top|above/.test(lower)){setArea('workspace');requestAnimationFrame(()=>viewer.current?.view('top'));response='Moving to the top view.';
  }else if(/front/.test(lower)){setArea('workspace');requestAnimationFrame(()=>viewer.current?.view('front'));response='Moving to the front view.';
  }else if(/analy|stress|deform/.test(lower)){setArea('workspace');play('analysis');response='Opening the response preview. You can switch between stress and amplified deformation, then compare with your baseline.';
  }else if(/save/.test(lower)){save();response='This design revision has been saved in your browser.';
  }else if(/hello|hi\b|hey/.test(lower)){response='Hello. I am your Trabecular copilot. Tell me the next design change, or ask me to inspect the current response.';}
  setReply(response);return response;
 }
